import os
import sys
import shutil

def is_under_home(path_abs, home_abs):
    return os.path.commonpath([os.path.abspath(path_abs), os.path.abspath(home_abs)]) == os.path.abspath(home_abs)

def main():
    if len(sys.argv) < 4:
        print("Usage: ncpmvdir source_dir dest_dir (-cp or -mv) [exts...]")
        sys.exit(1)

    source_dir = sys.argv[1]
    dest_dir = sys.argv[2]
    option = sys.argv[3]
    extensions = sys.argv[4:10]

    if option not in ['-cp', '-mv']:
        print("Invalid option. Must be -cp or -mv")
        sys.exit(1)

    exclude_exts = set()
    if len(extensions) > 6:
        print("Up to 6 extensions allowed.")
        sys.exit(1)
    for ext in extensions:
        if not ext.startswith('.'):
            ext = '.' + ext
        exclude_exts.add(ext.lower())

    home = os.path.expanduser('~')
    home_abs = os.path.abspath(home)
    source_abs = os.path.abspath(source_dir)
    dest_abs = os.path.abspath(dest_dir)

    if not os.path.exists(source_abs):
        print(f"Source directory {source_abs} does not exist.")
        sys.exit(1)
    if not is_under_home(source_abs, home_abs):
        print(f"Source directory {source_abs} not in home hierarchy.")
        sys.exit(1)
    if not is_under_home(dest_abs, home_abs):
        print(f"Destination directory {dest_abs} not in home hierarchy.")
        sys.exit(1)
    try:
        if os.path.samefile(source_abs, dest_abs):
            print("Source and destination are the same directory.")
            sys.exit(1)
    except OSError:
        pass  # Different devices or files, safe to proceed

    try:
        for root, dirs, files in os.walk(source_abs, topdown=False):
            relpath = os.path.relpath(root, source_abs)
            dest_root = os.path.join(dest_abs, relpath)

            for name in files:
                src_file = os.path.join(root, name)
                ext = os.path.splitext(name)[1].lower()
                do_copy = (option == '-cp') or (option == '-mv' and (ext not in exclude_exts))
                if do_copy:
                    os.makedirs(dest_root, exist_ok=True)
                    shutil.copy2(src_file, os.path.join(dest_root, name))
                if option == '-mv':
                    os.unlink(src_file)

            if not os.path.exists(dest_root):
                os.makedirs(dest_root, exist_ok=True)

            if option == '-mv':
                try:
                    if os.path.exists(root):
                        os.rmdir(root)
                except OSError as e:
                    print(f"Error deleting directory {root}: {e}")
                    sys.exit(1)
    except Exception as e:
        print(f"Error: {e}")
        sys.exit(1)

if __name__ == '__main__':
    main()
