using System;
using SkiaSharp;

public class ImageProcessor
{
    // Creates a grayscale color filter using a color matrix
    private static SKColorFilter CreateGrayscaleFilter()
    {
        float[] matrix = {
            // R       G       B       A      Const
            0.2126f, 0.7152f, 0.0722f, 0, 0, // Red channel
            0.2126f, 0.7152f, 0.0722f, 0, 0, // Green channel
            0.2126f, 0.7152f, 0.0722f, 0, 0, // Blue channel
            0,       0,       0,       1, 0  // Alpha channel
        };
        return SKColorFilter.CreateColorMatrix(matrix);
    }

    // Generates a color lookup table for quantization
    private static byte[] CreateLUT(int levels)
    {
        if (levels < 2) levels = 2; // Minimum 2 levels
        int step = 255 / (levels - 1);
        byte[] lut = new byte[256];

        for (int i = 0; i < 256; i++)
        {
            int value = (int)Math.Round((i / 255.0) * (levels - 1));
            lut[i] = (byte)(value * step);
        }
        return lut;
    }

    public static byte[] ProcessImage(
        string imagePath, 
        int zlibLevel = 6, 
        int? targetWidth = null,
        bool applyGrayscale = false,
        int colorLevels = 0)
    {
        using var bitmap = SKBitmap.Decode(imagePath);
        SKImage resizedImage = null;

        // 1. Resize if needed
        if (targetWidth.HasValue)
        {
            int height = (int)(bitmap.Height * (targetWidth.Value / (float)bitmap.Width));
            using var surface = SKSurface.Create(new SKImageInfo(targetWidth.Value, height));
            var canvas = surface.Canvas;

            canvas.Scale(
                (float)targetWidth / bitmap.Width, 
                (float)height / bitmap.Height);

            using var paint = new SKPaint { 
                FilterQuality = SKFilterQuality.High 
            };

            using var image = SKImage.FromBitmap(bitmap);
            canvas.DrawImage(image, 0, 0, paint);
            resizedImage = surface.Snapshot();
        }

        // 2. Use resized image or original
        using var sourceImage = resizedImage ?? SKImage.FromBitmap(bitmap);
        SKImage processedImage = sourceImage;

        // 3. Apply grayscale conversion
        if (applyGrayscale)
        {
            using var grayscaleFilter = CreateGrayscaleFilter();
            using var paint = new SKPaint { 
                ColorFilter = grayscaleFilter 
            };

            using var surface = SKSurface.Create(new SKImageInfo(
                processedImage.Width, 
                processedImage.Height));

            surface.Canvas.DrawImage(processedImage, 0, 0, paint);
            var newImage = surface.Snapshot();

            if (processedImage != sourceImage)
                processedImage.Dispose();

            processedImage = newImage;
        }

        // 4. Apply color reduction
        if (colorLevels > 0)
        {
            byte[] lut = CreateLUT(colorLevels);
            using var colorFilter = SKColorFilter.CreateTable(lut, lut, lut);
            using var paint = new SKPaint { 
                ColorFilter = colorFilter 
            };

            using var surface = SKSurface.Create(new SKImageInfo(
                processedImage.Width, 
                processedImage.Height));

            surface.Canvas.DrawImage(processedImage, 0, 0, paint);
            var newImage = surface.Snapshot();

            if (processedImage != sourceImage)
                processedImage.Dispose();

            processedImage = newImage;
        }

        // 5. Encode with compression
        using var options = new SKPngEncoderOptions { 
            ZLibLevel = zlibLevel 
        };

        using var encodedData = processedImage.Encode(options);
        return encodedData.ToArray();
    }
}

// === Example Usage ===
// byte[] pngData = ImageProcessor.ProcessImage(
//     "input.png",
//     zlibLevel: 9,
//     targetWidth: 200,
//     applyGrayscale: true,
//     colorLevels: 4
// );
