from abc import ABC, abstractmethod
from typing import List, Union
from functools import singledispatchmethod
from collections import defaultdict

# Base abstract class for museum exhibits with encapsulation
class Exhibit(ABC):
    def __init__(self, name: str):
        self._name = name  # Private attribute for encapsulation

    @abstractmethod
    def display(self):
        pass

    def get_name(self) -> str:
        return self._name

# Derived class for painting exhibits
class Painting(Exhibit):
    def __init__(self, name: str, artist: str):
        super().__init__(name)
        self._artist = artist  # Encapsulated attribute

    def get_artist(self) -> str:
        return self._artist

    def display(self):
        print(f"Displaying painting: {self.get_name()} by {self.get_artist()}")

# Derived class for sculpture exhibits
class Sculpture(Exhibit):
    def __init__(self, name: str, material: str):
        super().__init__(name)
        self._material = material  # Encapsulated attribute

    def get_material(self) -> str:
        return self._material

    def display(self):
        print(f"Displaying sculpture: {self.get_name()} made of {self.get_material()}")

# Additional derived class for digital art exhibits
class DigitalArt(Exhibit):
    def __init__(self, name: str, software: str):
        super().__init__(name)
        self._software = software  # Encapsulated attribute

    def get_software(self) -> str:
        return self._software

    def display(self):
        print(f"Displaying digital art: {self.get_name()} created with {self.get_software()}")

# Museum class demonstrating templates, method overloading, and data analysis
class Museum:
    def __init__(self):
        self.exhibits: List[Exhibit] = []  # Template with type hint

    @singledispatchmethod
    def add_exhibit(self, exhibit):
        """Add a single exhibit or list of exhibits using method overloading"""
        raise TypeError("Unsupported type")

    @add_exhibit.register
    def _(self, exhibit: Exhibit):
        self.exhibits.append(exhibit)

    @add_exhibit.register
    def _(self, exhibit_list: List):
        self.exhibits.extend(exhibit_list)

    def display_all(self):
        for exhibit in self.exhibits:
            exhibit.display()

    def analyze_exhibits(self) -> dict:
        """Data analysis: Count exhibit types"""
        counts = defaultdict(int)
        for exhibit in self.exhibits:
            counts[type(exhibit).__name__] += 1
        return dict(counts)

# Analytics class for data processing
class Analytics:
    @staticmethod
    def process_exhibits(exhibits: List[Exhibit]) -> List[str]:
        """Data processing: Extract exhibit names"""
        return [exhibit.get_name() for exhibit in exhibits]

# Main execution
if __name__ == "__main__":
    museum = Museum()

    # Add exhibits using overloaded add_exhibit method
    museum.add_exhibit(Painting("The Starry Night", "Vincent van Gogh"))
    museum.add_exhibit(Sculpture("David", "Marble"))
    museum.add_exhibit([Painting("The Persistence of Memory", "Salvador Dali"), DigitalArt("Digital Dream", "Photoshop")])

    # Display all exhibits (polymorphism in action)
    print("Exhibit Display:")
    museum.display_all()

    # Analyze exhibit data
    print("\nExhibit Analysis (Type Counts):")
    print(museum.analyze_exhibits())

    # Process exhibit data
    print("\nProcessing Exhibit Names:")
    print(Analytics.process_exhibits(museum.exhibits))
