        self.exhibit_map[exhibit.get_name()] = exhibit  # Map for fast lookup

    @add_exhibit.register
    def _(self, exhibit_list: List[Exhibit]):
        self.exhibits.extend(exhibit_list)
        for exhibit in exhibit_list:
            self.exhibit_map[exhibit.get_name()] = exhibit

    def display_all(self):
        """Polymorphic display of all exhibits (STL algorithm for_each equivalent)"""
        for exhibit in self.exhibits:
            exhibit.display()

    def analyze_exhibits(self) -> Dict[str, int]:
        """Data analysis: Count exhibit types (STL map equivalent)"""
        counts = defaultdict(int)
        for exhibit in self.exhibits:
            counts[type(exhibit).__name__] += 1
        return dict(counts)

    def sort_exhibits(self, key_func: Callable[[Exhibit], any] = None):
        """STL sort algorithm equivalent"""
        self.exhibits.sort(key_func=key_func)

    def find_exhibit(self, name: str) -> Exhibit:
        """Direct exhibit lookup using map (STL map::find equivalent)"""
        return self.exhibit_map.get(name)

    def get_exhibits_by_type(self, exhibit_type: Type[T]) -> Vector[T]:
        """Generic template method to filter exhibits by type (STL copy_if equivalent)"""
        return Vector[T]([exhibit for exhibit in self.exhibits if isinstance(exhibit, exhibit_type)])

# Analytics class with STL-like algorithms
class Analytics:
    @staticmethod
    def process_exhibits(exhibits: Vector[S]) -> List[str]:
        """Generic data processing method (STL transform equivalent)"""
        return [exhibit.get_name() for exhibit in exhibits]

    @staticmethod
    def filter_paintings(exhibits: Vector[Exhibit]) -> Vector[Painting]:
        """STL copy_if equivalent for filtering paintings"""
        return Vector[Painting]([e for e in exhibits if isinstance(e, Painting)])

    @staticmethod
    def calculate_total_name_length(exhibits: Vector[Exhibit]) -> int:
        """STL accumulate equivalent (sum of name lengths)"""
        return reduce(lambda acc, exhibit: acc + len(exhibit.get_name()), exhibits, 0)

    @staticmethod
    def concatenate_names(exhibits: Vector[Exhibit], separator: str = ", ") -> str:
        """STL accumulate equivalent (string concatenation)"""
        return reduce(lambda acc, exhibit: f"{acc}{separator}{exhibit.get_name()}", exhibits, "")[len(separator):]

