    [CommandMethod("DimensionPlateHoles")]
    public void DimensionPlateHoles()
    {
        Document doc = Application.DocumentManager.MdiActiveDocument;
        Database db = doc.Database;
        Editor ed = doc.Editor;

        try
        {
            using (Transaction trans = db.TransactionManager.StartTransaction())
            {
                // Lock document and get selection
                doc.LockDocument();

                // 1. Select plate entity
                PromptEntityResult per = ed.GetEntity("\nSelect plate entity: ");
                if (per.Status != PromptStatus.OK)
                {
                    ed.WriteMessage("\nInvalid selection.");
                    return;
                }

                // 2. Open selected plate entity
                Entity plate = trans.GetObject(per.ObjectId, OpenMode.ForRead) as Entity;
                if (plate == null)
                {
                    ed.WriteMessage("\nSelected object is not a valid entity.");
                    return;
                }

                // 3. Get plate bounds to determine origin
                BoundingBox bounds = plate.Bounds ?? throw new Exception("Could not get plate bounds");
                Point3d origin = bounds.MinPoint; // Assuming MinPoint is bottom-left corner

                // 4. Retrieve holes from plate (implementation depends on API specifics)
                List<HoleData> holes = GetPlateHoles(plate, trans);
                if (holes.Count == 0)
                {
                    ed.WriteMessage("\nNo holes found on selected plate.");
                    return;
                }

                // 5. Dimension settings
                double offset = 50.0; // Distance from plate to dimension lines
                DimensionStyle dimStyle = bounds.MinPoint.Z < 0.1 ? DimensionStyle.ANSI : DimensionStyle.ISO; // Example style selection

                // 6. Get model space block table record
                BlockTable bt = trans.GetObject(db.BlockTableId, OpenMode.ForRead) as BlockTable;
                BlockTableRecord btr = trans.GetObject(bt[BlockTableRecord.ModelSpace], OpenMode.ForWrite) as BlockTableRecord;

                // 7. Process each hole
                foreach (HoleData hole in holes)
                {
                    // Calculate relative coordinates
                    double relX = hole.Center.X - origin.X;
                    double relY = hole.Center.Y - origin.Y;

                    // Create horizontal (X) dimension
                    AlignedDimension xDim = CreateHorizontalDimension(origin, hole.Center, relX, offset, dimStyle);
                    btr.AppendEntity(xDim);
                    trans.AddNewlyCreatedDBObject(xDim, true);

                    // Create vertical (Y) dimension
                    AlignedDimension yDim = CreateVerticalDimension(origin, hole.Center, relY, offset, dimStyle);
                    btr.AppendEntity(yDim);
                    trans.AddNewlyCreatedDBObject(yDim, true);
                }

                // 8. Finalize transaction
                trans.Commit();
                ed.WriteMessage($"\nSuccessfully dimensioned {holes.Count * 2} dimensions.");
            }
        }
        catch (Exception ex)
        {
            ed.WriteMessage($"\nError: {ex.Message}");
        }
    }

    // Helper method to create horizontal dimensions
    private AlignedDimension CreateHorizontalDimension(Point3d origin, Point3d holeCenter, double length, double offset, DimensionStyle style)
    {
        AlignedDimension dim = new AlignedDimension
        {
            // Set dimension endpoints (horizontal line)
            XLine1Point = new Point3d(origin.X, origin.Y, 0),
            XLine2Point = new Point3d(holeCenter.X, origin.Y, 0),

            // Position dimension line below the plate
            DimensionLinePoint = new Point3d(origin.X, origin.Y - offset, 0),

            // Set explicit dimension text
            DimensionText = length.ToString("F2"),

            // Force text override to ensure relative value display
            TextOverride = length.ToString("F2"),

            // Apply dimension style
            DimensionStyle = style
        };

        dim.SetDatabaseDefaults();
        return dim;
    }

    // Helper method to create vertical dimensions
    private AlignedDimension CreateVerticalDimension(Point3d origin, Point3d holeCenter, double length, double offset, DimensionStyle style)
    {
        AlignedDimension dim = new AlignedDimension
        {
            // Set dimension endpoints (vertical line)
            XLine1Point = new Point3d(origin.X, origin.Y, 0),
            XLine2Point = new Point3d(origin.X, holeCenter.Y, 0),

            // Position dimension line to the left of the plate
            DimensionLinePoint = new Point3d(origin.X - offset, origin.Y, 0),

            // Set explicit dimension text
            DimensionText = length.ToString("F2"),

            // Force text override to ensure relative value display
            TextOverride = length.ToString("F2"),

