        adj[u].push_back({v, w});
        adj[v].push_back({u, w});
    }
    vector<ll> d1 = dijkstra(1, n);
    vector<ll> dn = dijkstra(n, n);
    for (int i = 0; i < k; ++i) {
        ll a, b;
