        cp_analytical = 1.0 - 4.0 * sin(theta).^2;
    catch
        theta = [];
        cp_analytical = [];
    end

    for i = 1:n
        x_i = midpoints(i, 1);
        y_i = midpoints(i, 2);
        tx = tangents(i, 1);
        ty = tangents(i, 2);

        u_ind = 0;
        v_ind = 0;

        for j = 1:n
            x_a_j = panels(j, 1);
            y_a_j = panels(j, 2);
            x_b_j = panels(j, 3);
            y_b_j = panels(j, 4);
            L_j = panel_lengths(j);
            sigma_j = sigma(j);

            % Use 3-point Gauss quadrature for integration
            for k = 1:3
                s = gauss_points(k, 1);
