import numpy as np

def determinant_lu(matrix):
    """Compute determinant using LU decomposition with partial pivoting (O(n³))."""
    n = len(matrix)
    if n != len(matrix[0]):
        raise ValueError("Matrix must be square for determinant calculation.")

    # Make a copy to avoid modifying original
    mat = [row[:] for row in matrix]
    sign = 1

    for col in range(n):
        # Find pivot with maximum absolute value in current column
        pivot_row = col
        for r in range(col + 1, n):
            if abs(mat[r][col]) > abs(mat[pivot_row][col]):
                pivot_row = r

        if mat[pivot_row][col] == 0:
            return 0  # Singular matrix

        if pivot_row != col:
            mat[col], mat[pivot_row] = mat[pivot_row], mat[col]
            sign *= -1

        # Eliminate all rows below current pivot row
        for r in range(col + 1, n):
            factor = mat[r][col] / mat[col][col]
            for c in range(col, n):
                mat[r][c] -= factor * mat[col][c]

    # Product of diagonal elements of upper triangular matrix
    det = 1
    for i in range(n):
        det *= mat[i][i]

    return det * sign

def get_submatrix(matrix, row_exclude, col_exclude):
    """Generate submatrix by removing specified row and column."""
    return [
        [matrix[i][j] for j in range(len(matrix)) if j != col_exclude]
        for i in range(len(matrix)) if i != row_exclude
    ]

def minor_efficient(matrix, row, col):
    """
    Compute the minor of a matrix element using LU decomposition for determinant.

    Parameters:
    - matrix: A square matrix (list of lists)
    - row: Row index of the element
    - col: Column index of the element

    Returns:
    - The minor value (determinant of the submatrix after removing row and column)

    Time Complexity: O(n³) - Gaussian elimination for determinant
    Space Complexity: O(n²) - Submatrix storage
    """
    n = len(matrix)
    # Validate matrix is square
    if any(len(row_list) != n for row_list in matrix):
        raise ValueError("Matrix must be square (all rows must have equal length)")

    # Validate indices
    if not (0 <= row < n and 0 <= col < n):
        raise IndexError("Row/column indices out of bounds")

    # Generate submatrix
    submatrix = get_submatrix(matrix, row, col)

    # Compute determinant of submatrix using LU decomposition
    return determinant_lu(submatrix)

def minor_numpy(matrix, row, col):
    """
    Compute the minor using NumPy's optimized linear algebra routines.

    Time Complexity: O(n³) - Optimized BLAS backend
    Space Complexity: O(n²) - Submatrix storage
    """
    n = len(matrix)
    if n != len(matrix[0]):
        raise ValueError("Matrix must be square")
    if not (0 <= row < n and 0 <= col < n):
        raise IndexError("Indices out of bounds")

    # Convert to NumPy array
    np_mat = np.array(matrix, dtype=np.float64)
    # Create submatrix by deleting row and column
    submatrix = np.delete(np.delete(np_mat, row, axis=0), col, axis=1)
    return np.linalg.det(submatrix)

# Example usage
mat_3x3 = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]
print(f"LU-based minor: {minor_efficient(mat_3x3, 0, 0)}")  # Output: -3
print(f"NumPy minor: {minor_numpy(mat_3x3, 0, 0)}")        # Output: -3.0
