   - Clear exception messages for debugging

3. **C++ Best Practices**:
   - Template metaprogramming for type safety
   - Bounds-checked accessors
   - Integration with Eigen for production-grade performance

4. **Edge Case Coverage**:
   - Singular matrices (returns 0 determinant)
   - Non-square matrices (throws ValueError)
   - Out-of-bounds indices (throws IndexError)

```python
// C++ code with const correctness and Eigen integration
#include <array>
#include <stdexcept>
#include <Eigen/Dense> // Must install Eigen library

// Fixed-size matrix class with const correctness
template<typename T, size_t Size>
class Matrix {
    std::array<std::array<T, Size>, Size> data;
public:
    // Const accessor with bounds checking
    const std::array<T, Size>& operator[](size_t row) const {
        if (row >= Size) {
            throw std::out_of_range("Row index out of bounds");
        }
        return data[row];
    }

    // Constructor with initializer list (C++11)
    Matrix(std::initializer_list<std::array<T, Size>> list) {
        auto it = list.begin();
        for (size_t i = 0; i < Size && it != list.end(); ++i, ++it) {
            data[i] = *it;
        }
    }

    // 2x2 matrix minor method (const-correct)
    T minor2x2(size_t row, size_t col) const {
        if (Size != 2) {
            throw std::domain_error("minor2x2 requires a 2x2 matrix");
        }
        if (row >= 2 || col >= 2) {
            throw std::out_of_range("Row/col indices must be 0 or 1");
        }
        return data[1 - row][1 - col]; // O(1) operation
    }
};

// Eigen-based minor calculation for large matrices
template<typename T>
double computeMinor(const Eigen::Matrix<T, Eigen::Dynamic, Eigen::Dynamic>& matrix, 
                   int row, int col) {
    // Input validation
    if (row < 0 || row >= matrix.rows() || 
        col < 0 || col >= matrix.cols()) {
        throw std::out_of_range("Row/column indices out of bounds");
    }

    // Efficient submatrix creation (O(n²) time)
    int n_rows = matrix.rows() - 1;
    int n_cols = matrix.cols() - 1;
    Eigen::Matrix<T, Eigen::Dynamic, Eigen::Dynamic> submatrix(n_rows, n_cols);

    int sub_i = 0;
    for (int i = 0; i < matrix.rows(); ++i) {
        if (i == row) continue;
        int sub_j = 0;
        for (int j = 0; j < matrix.cols(); ++j) {
            if (j == col) continue;
            submatrix(sub_i, sub_j) = matrix(i, j);
            ++sub_j;
        }
        ++sub_i;
    }

    // O(n³) determinant calculation using Eigen's optimized routines
    return submatrix.determinant();
}

// Example usage
int main() {
    // 2x2 matrix example
    Matrix<int, 2> mat2x2({{1, 2}, {3, 4}});
    try {
        int m = mat2x2.minor2x2(0, 0); // Returns 4
    } catch (const std::exception& e) {
        // Handle error
    }

    // 3x3 matrix example with Eigen
    Eigen::Matrix3d mat3x3;
    mat3x3 << 1, 2, 3,
              4, 5, 6,
              7, 8, 9;

    try {
        double minor = computeMinor(mat3x3, 0, 0); // Returns -3
    } catch (const std::exception& e) {
        // Handle error
    }

    return 0;
}
