    # Compute the model values on the grid
    model_values = zeros(size(P1));
    for i = 1:size(P1, 1)
        for j = 1:size(P1, 2)
            p = [P1(i,j); P2(i,j)];
            model_values(i,j) = quadratic_model(p, x, B);
        end
    end

    # Create plot
    figure;
    hold on;

    # Plot contour lines
    contour(P1, P2, model_values, 30, 'ShowText', 'on');

    # Plot the trust region solutions for different Δ values
    delta_values = linspace(0, 2, 100);
    solutions = [];

    # Initial guess (along the negative gradient direction)
    g = gradient(x);
    if norm(g) > 0
        p0 = -g / norm(g);
    else
        p0 = [0; 0];
    end

    # Precompute gradient and Hessian
    g = gradient(x);
    B = hessian(x);

    # Solve the trust region subproblem for each Δ
    for k = 1:length(delta_values)
        delta = delta_values(k);

        try
            # Solve the Newton system
            p_newton = -B \ g;

            # If the Newton step is within the trust region, use it
            if norm(p_newton) <= delta
                p_sol = p_newton;
            else
                # Otherwise, use a constrained optimization approach

                # Define objective function
                obj = @(p) quadratic_model(p, x, B);

                # Define constraint: ||p|| <= delta
                nonlcon = @(p)deal([], norm(p)^2 - delta^2);

                # Solve with fmincon
                options = optimoptions('fmincon','Display','off','Algorithm','sqp','TolFun',1e-8);
                [p_sol, ~] = fmincon(obj, p0, [], [], [], [], [], [], nonlcon, options);
            end
        catch
            # If Hessian is singular or optimization fails, use Cauchy point
            curvature = g' * B * g;
            if curvature <= 0
                # Non-positive curvature, use steepest descent
                p_sol = -delta * g / norm(g);
            else
                # Cauchy point
                alpha = norm(g)^2 / curvature;
                p_cauchy = -alpha * g;
                if norm(p_cauchy) <= delta
                    p_sol = p_cauchy;
                else
                    p_sol = -delta * g / norm(g);
                end
            end
        end

        solutions = [solutions, p_sol];
        plot(p_sol(1), p_sol(2), 'r.', 'MarkerSize', 2);
