    solutions = cell2mat(solutions);
    plot(solutions(1, :), solutions(2, :), 'r-', 'LineWidth', 1, 'HandleVisibility', 'off');

    # Plot the center point
    plot(0, 0, 'k+', 'MarkerSize', 10);

