% Function to define the Rosenbrock function
function fx = f(x)
    fx = 10 * (x(2) - x(1)^2)^2 + (1 - x(1))^2;
end

% Function to compute the gradient
function grad = gradient(x)
    df_dx1 = -40 * x(1) * (x(2) - x(1)^2) - 2 * (1 - x(1));
    df_dx2 = 20 * (x(2) - x(1)^2);
    grad = [df_dx1; df_dx2];
end

% Function to compute the Hessian
function H = hessian(x)
    H = zeros(2);
    H(1, 1) = -40 * (x(2) - x(1)^2) + 80 * x(1)^2 - 2;
    H(1, 2) = -40 * x(1);
    H(2, 1) = -40 * x(1);
    H(2, 2) = 20;
end

% Function to define the quadratic model
function model = quadratic_model(p, x, B)
    fx = f(x);
    grad = gradient(x);
    model = fx + grad' * p + 0.5 * p' * B * p;
end

