def get_table_columns(table_name):
    """Helper to get columns for a table from schema"""
    if table_name not in schema:
        raise UnknownTableError(table_name)
    return list(schema[table_name].keys())

def resolve_column(column_name, alias_map):
    """Resolve ambiguous column names based on available tables"""
    if '.' in column_name:
        alias, col = column_name.split('.', 1)
        if alias not in alias_map:
            raise UnknownTableError(alias)
        actual_table = alias_map[alias]
        if col not in schema[actual_table]:
            raise UnknownColumnError(col, actual_table)
        return f"{actual_table}.{col}"
    else:
        matches = []
        for table in alias_map.values():
            if column_name in schema[table]:
                matches.append(table)

        if not matches:
            raise UnknownColumnError(column_name)
        if len(matches) > 1:
            raise AmbiguousColumnError(column_name, matches)

        return f"{matches[0]}.{column_name}"

def parse_condition(condition_ast, alias_map):
    """Recursively parse SQL condition with schema validation"""
    if not isinstance(condition_ast, dict) or 'op' not in condition_ast:
        raise QueryError("Invalid condition format")

    op = condition_ast['op']
    left = condition_ast.get('left')
    right = condition_ast.get('right')

    # Handle nested conditions
    if op in ['AND', 'OR']:
        left_val = parse_condition(left, alias_map)
        right_val = parse_condition(right, alias_map)
        return f"({left_val} {op} {right_val})"

    # Handle comparison operators
    if op in ['>', '<', '>=', '<=', '=', '!=']:
        # Resolve column names
        if isinstance(left, str):
            left = resolve_column(left, alias_map)
        if isinstance(right, str):
            right = resolve_column(right, alias_map)

        return f"{left} {op} {right}"

    raise InvalidOperatorError(op)

def parse_from(from_clause, alias_map):
    """Parse FROM clause with schema validation"""
    if not isinstance(from_clause, list):
        from_clause = [from_clause]

    tables = []
    for table_def in from_clause:
        if not isinstance(table_def, dict) or 'table' not in table_def:
            raise QueryError("Invalid table reference")

        full_name = table_def['table']
        parts = full_name.split()
        table_name = parts[0]
        alias = parts[1] if len(parts) > 1 else table_name

        if table_name not in schema:
            raise UnknownTableError(table_name)

        alias_map[alias] = table_name
        tables.append(table_name)

    if len(tables) == 1:
        return Scan(tables[0])

    # Build cross product for multiple tables
    ra = Scan(tables[0])
    for table in tables[1:]:
        ra = CrossProduct(ra, Scan(table))
    return ra

def is_join_condition(condition, alias_map):
    """Detect if a condition is a join condition"""
    if condition['op'] == '=' and isinstance(condition['left'], str) and isinstance(condition['right'], str):
        left_parts = condition['left'].split('.')
        right_parts = condition['right'].split('.')

        if len(left_parts) == 2 and len(right_parts) == 2:
            left_table = alias_map.get(left_parts[0], None)
            right_table = alias_map.get(right_parts[0], None)

            if left_table and right_table and left_table != right_table:
                return True
    return False

def parse_query(sql_ast):
    """Main query parser with comprehensive error handling"""
    try:
        # Validate SQL structure
        if sql_ast.get('type') != 'select':
            raise MissingClauseError('SELECT')

        if 'columns' not in sql_ast:
            raise MissingClauseError('SELECT columns')

        if 'from' not in sql_ast:
            raise MissingClauseError('FROM')

        alias_map = {}

        # 1. Parse FROM clause
        ra = parse_from(sql_ast['from'], alias_map)

        # 2. Parse WHERE clause
        if 'where' in sql_ast:
            condition = parse_condition(sql_ast['where'], alias_map)

            # Detect join conditions
            if isinstance(ra, CrossProduct) and is_join_condition(sql_ast['where'], alias_map):
                left_tables = []
                right_tables = []

                def collect_tables(node, tables):
                    if isinstance(node, Scan):
                        tables.append(node.table_name)
                    elif isinstance(node, CrossProduct):
                        collect_tables(node.left, tables)
                        collect_tables(node.right, tables)

                left_tables = []
                collect_tables(ra.left, left_tables)
                right_tables = []
                collect_tables(ra.right, right_tables)

                ra = Join(ra.left, ra.right, condition)

            else:
                ra = Select(condition, ra)

        # 3. Parse SELECT clause with column validation
        select_columns = []
        for col in sql_ast['columns']:
            if col == '*':
                select_columns = ['*']
                break
            if isinstance(col, str):
                select_columns.append(resolve_column(col, alias_map))

        ra = Project(select_columns, ra)
        return ra

    except QueryError as e:
        print(f"Query Error: {e}")
        return None
    except Exception as e:
        print(f"Internal Error: {e}")
        return None

