    def __repr__(self): return f"σ(Scan({self.table_name}))"

class Select:
    def __init__(self, condition, child):
        self.condition = condition
        self.child = child
    def __repr__(self): return f"σ({self.condition}, {self.child})"

class Project:
    def __init__(self, attributes, child):
        self.attributes = attributes
        self.child = child
    def __repr__(self): return f"π({self.attributes}, {self.child})"

class CrossProduct:
    def __init__(self, left, right):
        self.left = left
        self.right = right
    def __repr__(self): return f"×({self.left}, {self.right})"

class Join:
    def __init__(self, left, right, condition):
