```go
package main

import (
	"fmt"
	"math/rand"
	"time"
)

// Calculate fitness (higher = better)
// Similar to risk-return ratio in finance
func fitness(individual []float64, returns []float64, risks []float64) float64 {
	weightedReturn := 0.0
	weightedRisk := 0.0

	for i := range individual {
		weightedReturn += individual[i] * returns[i]
		weightedRisk += individual[i] * risks[i]
	}

	// Avoid division by zero with tiny number
	return weightedReturn / (weightedRisk + 0.00000001)
}

// Create random portfolio weights that sum to 1
func createIndividual(nAssets int) []float64 {
	weights := make([]float64, nAssets)
	sum := 0.0

	// Create random values
	for i := range weights {
		weights[i] = rand.Float64()
		sum += weights[i]
	}

	// Normalize to sum to 1
	for i := range weights {
		weights[i] /= sum
	}

	return weights
}

// Combine two parents to create child
func crossover(parent1, parent2 []float64) []float64 {
	alpha := rand.Float64()
	child := make([]float64, len(parent1))

	// Blend parent values
	for i := range child {
		child[i] = alpha*parent1[i] + (1-alpha)*parent2[i]
	}

	// Normalize to sum to 1
	sum := 0.0
	for _, w := range child {
		sum += w
	}
	for i := range child {
		child[i] /= sum
	}

	return child
}

// Randomly modify weights
func mutate(individual []float64, mutationRate float64) []float64 {
	if rand.Float64() < mutationRate {
		idx := rand.Intn(len(individual))

		// Add small random change
		individual[idx] += rand.Float64()*0.2 - 0.1

		// Keep between 0 and 1
		if individual[idx] < 0 {
			individual[idx] = 0
		} else if individual[idx] > 1 {
			individual[idx] = 1
		}

		// Renormalize
		sum := 0.0
		for _, w := range individual {
			sum += w
		}
		for i := range individual {
			individual[i] /= sum
		}
	}

	return individual
}

// Select best from random group
func selectParent(population [][]float64, returns []float64, risks []float64) []float64 {
	tournamentSize := 3
	bestFitness := -1.0
	var bestIndex int

	// Pick random candidates
	for i := 0; i < tournamentSize; i++ {
		idx := rand.Intn(len(population))
		currentFitness := fitness(population[idx], returns, risks)

		if currentFitness > bestFitness {
			bestFitness = currentFitness
			bestIndex = idx
		}
	}

	return population[bestIndex]
}

// Main genetic algorithm
func geneticAlgorithm(nAssets int, returns []float64, risks []float64, nGenerations, popSize int) []float64 {
	// Initialize population
	population := make([][]float64, popSize)
	for i := range population {
		population[i] = createIndividual(nAssets)
	}

	// Evolve through generations
	for generation := 0; generation < nGenerations; generation++ {
		// Find best solution so far
		bestIndex := 0
		bestFitness := fitness(population[0], returns, risks)

		for i := 1; i < popSize; i++ {
			currentFitness := fitness(population[i], returns, risks)
			if currentFitness > bestFitness {
				bestFitness = currentFitness
				bestIndex = i
			}
		}

		// Keep best solution (elitism)
		newPopulation := [][]float64{population[bestIndex]}

		// Create new solutions
		for len(newPopulation) < popSize {
			// Select parents
			parent1 := selectParent(population, returns, risks)
			parent2 := selectParent(population, returns, risks)

			// Create child
			child := crossover(parent1, parent2)
			child = mutate(child, 0.1) // 10% mutation chance

			newPopulation = append(newPopulation, child)
		}

		population = newPopulation
	}

	// Return final best solution
	bestIndex := 0
	bestFitness := fitness(population[0], returns, risks)

	for i := 1; i < popSize; i++ {
		currentFitness := fitness(population[i], returns, risks)
		if currentFitness > bestFitness {
			bestFitness = currentFitness
			bestIndex = i
		}
	}

	return population[bestIndex]
}

func main() {
	rand.Seed(time.Now().UnixNano())

	// Problem setup
	nAssets := 5
	returns := make([]float64, nAssets)
	risks := make([]float64, nAssets)

	// Create random returns and risks
	for i := 0; i < nAssets; i++ {
		returns[i] = rand.Float64()*10 // 0-10% returns
		risks[i] = rand.Float64()*5    // 0-5% risks
	}

	// Run algorithm
	bestWeights := geneticAlgorithm(nAssets, returns, risks, 100, 50)

	// Show results
	fmt.Printf("Optimal weights: %v\n", bestWeights)
	fmt.Printf("Returns: %v\n", returns)
	fmt.Printf("Risks: %v\n", risks)
}
