# Note: This is a Unity C# script formatted in Python for instructional purposes.
# The script renders trajectory dots on a UI Canvas with gravity consideration.

"""
using UnityEngine;
using UnityEngine.UI;

public class TrajectoryPrediction : MonoBehaviour
{
    public Transform ball;          // The draggable object
    public Canvas canvas;           // UI Canvas for trajectory dots
    public RectTransform trajectoryParent; // Parent RectTransform for dots
    public GameObject dotPrefab;    // Prefab for trajectory dots (UI Image)
    public int trajectorySteps = 10; // Number of dots to show
    public float timeBetweenSteps = 0.1f; // Time interval between steps
    public float velocityMultiplier = 0.1f; // Sensitivity for drag velocity
    public float gravity = -9.81f;  // Gravity scale (should match Physics2D.gravity)

    private List<GameObject> trajectoryDots = new List<GameObject>();
    private Vector2 initialVelocity;
    private bool isDragging = false;

    void Start()
    {
        // Initialize trajectory dots
        for (int i = 0; i < trajectorySteps; i++)
        {
            GameObject dot = Instantiate(dotPrefab, trajectoryParent);
            dot.SetActive(false);
            trajectoryDots.Add(dot);
        }
    }

    void Update()
    {
        if (Input.GetMouseButtonDown(0))
        {
            isDragging = true;
            // Start tracking mouse position
            lastMousePosition = Input.mousePosition;
        }

        if (isDragging)
        {
            // Calculate velocity from mouse movement
            Vector3 currentMouse = Input.mousePosition;
            Vector2 delta = currentMouse - lastMousePosition;
            initialVelocity = delta * velocityMultiplier;

            // Move ball to mouse position
            Vector3 worldPos = Camera.main.ScreenToWorldPoint(currentMouse);
            ball.position = worldPos;
            lastMousePosition = currentMouse;

            UpdateTrajectoryDots();
        }

        if (Input.GetMouseButtonUp(0))
        {
            isDragging = false;
            ClearTrajectoryDots();

            // Apply velocity to ball
            Rigidbody2D rb = ball.GetComponent<Rigidbody2D>();
            if (rb != null)
            {
                rb.velocity = initialVelocity;
            }
        }
    }

    void UpdateTrajectoryDots()
    {
        Vector3 ballPos = ball.position;
        for (int i = 0; i < trajectorySteps; i++)
        {
            float t = (i + 1) * timeBetweenSteps; // Start from small time step
            // Calculate position with gravity
            float x = ballPos.x + initialVelocity.x * t;
            float y = ballPos.y + initialVelocity.y * t + 0.5f * gravity * t * t;

            Vector3 worldPos = new Vector3(x, y, ballPos.z);
            Vector3 screenPos = Camera.main.WorldToScreenPoint(worldPos);

            // Convert to canvas position
            Vector2 localPos;
            RectTransformUtility.ScreenPointToLocalPointInRectangle(
                trajectoryParent,
                screenPos,
                canvas.worldCamera,
                out localPos
            );

            // Position the dot
            if (i < trajectoryDots.Count)
            {
                GameObject dot = trajectoryDots[i];
                dot.SetActive(true);
                dot.GetComponent<RectTransform>().anchoredPosition = localPos;
            }
        }
    }

    void ClearTrajectoryDots()
    {
        foreach (GameObject dot in trajectoryDots)
        {
            dot.SetActive(false);
        }
    }
}
