# Configure prayer time calculations
class PrayerCalculator:
    def __init__(self, timezone_offset=2):  # Egypt uses EET (UTC+2)
        self.calculator = praytimes.PrayTimes()
        self.calculator.adjust({'timeformat': '24h', 'highlat': 'AngleBased'})
        self.timezone_offset = timezone_offset

    def calculate(self, date, latitude, longitude):
        if latitude is None or longitude is None:
            return None

        self.calculator.set_date(date)
        times = self.calculator.get_times(date, (latitude, longitude), self.timezone_offset)

        # Map praytimes output to standard prayer names
        return {
            'Fajr': times['fajr'],
            'Dhuhr': times['dhuhr'],
            'Asr': times['asr'],
            'Maghrib': times['maghrib'],
            'Isha': times['isha']
        }

# Generate prayer times for the entire year (2023)
def generate_prayer_data(governorates):
    prayer_data = {}
    calculator = PrayerCalculator()

    # Generate all dates in 2023
    start_date = datetime(2023, 1, 1)
    end_date = datetime(2023, 12, 31)
    delta = timedelta(days=1)

    current_date = start_date
    while current_date <= end_date:
        date_str = current_date.strftime('%Y-%m-%d')

        for gov, info in governorates.items():
            latitude = info['latitude']
            longitude = info['longitude']

            # Calculate prayer times for this date and governorate
            times = calculator.calculate(current_date, latitude, longitude)

            if times:
                # Initialize governorate data if not exists
                if gov not in prayer_data:
                    prayer_data[gov] = {
                        'latitude': latitude,
                        'longitude': longitude,
                        'dates': {}
                    }

                # Store prayer times
                prayer_data[gov]['dates'][date_str] = {
                    'Fajr': times['Fajr'],
                    'Dhuhr': times['Dhuhr'],
                    'Asr': times['Asr'],
                    'Maghrib': times['Maghrib'],
                    'Isha': times['Isha']
                }
            else:
                # Skip if coordinates are missing
                continue

        current_date += delta

    return prayer_data

