use std::collections::HashMap;
use std::ffi::CString;
use std::os::unix::process::CommandExt;
use std::process::Command;
use std::ptr;
use nix::mount::{mount, MsFlags};
use nix::sys::signal;
use nix::sys::signal::{SigHandler, Signal};
use nix::sys::wait::{waitpid, WaitStatus};
use nix::unistd::{fork, ForkResult};
use libc::{self, pid_t};
use clap::{Arg, Command as ClapCommand, Subcommand};

struct Service {
    status: String,
    cmd: Vec<String>,
    pid: Option<pid_t>,
}

struct SysXInit {
    services: HashMap<String, Service>,
}

impl SysXInit {
    fn new() -> Self {
        let mut services = HashMap::new();
        services.insert("getty".to_string(), Service {
            status: "stopped".to_string(),
            cmd: vec!["agetty".to_string(), "--noclear".to_string(), "tty1".to_string(), "linux".to_string()],
            pid: None,
        });
        Self { services }
    }

    fn start_service(&mut self, name: &str) -> Result<(), String> {
        let service = match self.services.get_mut(name) {
            Some(s) => s,
            None => return Err(format!("Service {} not found", name)),
        };

        if service.status == "running" {
            return Err(format!("Service {} already running", name));
        }

        match unsafe { fork() } {
            Ok(ForkResult::Child) => {
                // Child process
                let cstr_args: Vec<CString> = service.cmd.iter()
                    .map(|s| CString::new(s.as_str()).unwrap())
                    .collect();
                let mut c_args: Vec<*const libc::c_char> = cstr_args.iter()
                    .map(|s| s.as_ptr())
                    .collect();
                c_args.push(ptr::null());

                // Execute the command
                unsafe {
                    libc::execvp(c_args[0], c_args.as_ptr());
                }
                // If we get here, exec failed
                eprintln!("Failed to execute {}", service.cmd[0]);
                libc::exit(1);
            },
            Ok(ForkResult::Parent { child }) => {
                service.pid = Some(child);
                service.status = "running".to_string();
                println!("Started {} (PID: {})", name, child);
            },
            Err(e) => return Err(format!("Fork failed: {}", e)),
        }

        Ok(())
    }

    fn stop_service(&mut self, name: &str) -> Result<(), String> {
        let service = match self.services.get_mut(name) {
            Some(s) if s.status == "running" => s,
            _ => return Err(format!("Service {} not running", name)),
        };

        let pid = service.pid.ok_or("No PID")?;
        unsafe {
            libc::kill(pid, Signal::SIGTERM as i32);
        }
        service.status = "stopped".to_string();
        service.pid = None;
        println!("Stopped {}", name);
        Ok(())
    }
}

fn mount_filesystems() -> Result<(), String> {
    let mounts = vec![
        ("proc", "/proc", "proc"),
        ("sysfs", "/sys", "sysfs"),
        ("tmpfs", "/dev", "tmpfs"),
    ];

    for (fs_type, path, m_type) in mounts {
        std::fs::create_dir_all(path).map_err(|e| format!("Failed to create {}: {}", path, e))?;
        mount(Some(fs_type), path, Some(m_type), MsFlags::empty(), None as Option<()>)
            .map_err(|e| format!("Mount failed: {}", e))?;
    }
    Ok(())
}

static mut SIGNAL_RECEIVED: bool = false;

extern "C" fn handle_signal(_: libc::c_int) {
    unsafe {
        SIGNAL_RECEIVED = true;
    }
}

fn main() {
    if std::process::id() != 1 {
        eprintln!("This must run as PID 1");
        std::process::exit(1);
    }

    // Mount essential filesystems
    if let Err(e) = mount_filesystems() {
        eprintln!("Mount error: {}", e);
        std::process::exit(1);
    }

    // Setup signal handlers
    unsafe {
        signal::signal(Signal::SIGINT, SigHandler::Handler(handle_signal))
            .expect("Failed to set SIGINT handler");
        signal::signal(Signal::SIGTERM, SigHandler::Handler(handle_signal))
            .expect("Failed to set SIGTERM handler");
    }

    let mut init = SysXInit::new();

    // Start basic services
    if let Err(e) = init.start_service("getty") {
        eprintln!("Failed to start getty: {}", e);
        // Continue anyway?
    }

    println!("sysx init system running...");

    // Main loop: wait for child processes
    loop {
        match waitpid(None, None) {
            Ok(WaitStatus::Exited(pid, status)) => {
                println!("Child {} exited with status {}", pid, status);
            }
            Ok(WaitStatus::Signaled(pid, signal, _)) => {
                println!("Child {} killed by signal {}", pid, signal);
            }
            Err(e) if e == nix::errno::Errno::EINTR => {
                // Check if we need to shutdown
                if unsafe { SIGNAL_RECEIVED } {
                    break;
                }
            }
            Err(e) => {
                eprintln!("Waitpid error: {}", e);
                break;
            }
            _ => {}
        }
    }

    // Shutdown sequence
    println!("Shutting down...");
    if let Err(e) = init.stop_service("getty") {
        eprintln!("Shutdown error: {}", e);
    }

    // Unmount filesystems
    for &(_, path, _) in &["proc", "sys", "dev"] {
        match nix::mount::umount(path) {
            Ok(()) => println!("Unmounted {}", path),
            Err(e) => eprintln!("Failed to unmount {}: {}", path, e),
        }
    }

    // Exit
    std::process::exit(0);
}

