    sequence = zeros(1, length);
    current = initialState;
    for i = 1:length
        sequence(i) = current;
        if current == 0
            current = randsrc(1,1,[0 1; transitionProbs{0}(1) transitionProbs{0}(2)]);
        else
            current = randsrc(1,1,[0 1; transitionProbs{1}(1) transitionProbs{1}(2)]);
        end
    end
end
```

#### 2. **Context-Adaptive Arithmetic Coding (Encoding)**
```matlab
function encodedBits = arithmeticEncode(sequence, transitionProbs)
    low = 0.0; high = 1.0;
    context = 'initial';
    for i = 1:length(sequence)
        symbol = sequence(i);
        if isequal(context, 'initial') || context == 0
            p0 = transitionProbs{0}(1);
        else
            p0 = transitionProbs{1}(1);
        end
        width = high - low;
        if symbol == 0
            high = low + p0 * width;
        else
            low = low + p0 * width;
        end
        context = symbol;
    end
    value = (low + high)/2;
    encodedBits = dec2bin(typecast(single(value), 'uint32'), 32);
    encodedBits(encodedBits == ' ') = [];
end
```

#### 3. **Context-Adaptive Arithmetic Coding (Decoding)**
```matlab
function decodedSequence = arithmeticDecode(bitstream, length, transitionProbs)
    bitstreamLength = numel(bitstream);
    value = bin2dec(bitstream) / (2^bitstreamLength);  % Correct normalization
    low = 0.0; high = 1.0;
    decodedSequence = zeros(1, length);
    context = 'initial';
    for i = 1:length
        if isequal(context, 'initial') || context == 0
            p0 = transitionProbs{0}(1);
        else
            p0 = transitionProbs{1}(1);
        end
        width = high - low;
        split = low + p0 * width;
        if value < split
            decodedSequence(i) = 0;
            high = split;
        else
            decodedSequence(i) = 1;
            low = split;
        end
        context = decodedSequence(i);
    end
end
```

#### 4. **Noisy Channel Simulation (BSC)**
```matlab
function receivedBits = bscChannel(bitstream, ber)
    % Convert bitstream string to logical array
    encodedVector = bitstream == '1';

    % Create BSC object
    bsc = comm.BinarySymmetricChannel('BitProbability', ber);

    % Apply BSC
    receivedVector = bsc(encodedVector);

    % Convert back to bitstring
    receivedBits = char(receivedVector + '0');
end
```

#### 5. **BER Calculation**
```matlab
function ber = calculateBER(transmitted, received)
    maxLength = max(length(transmitted), length(received));
    transmitted = [transmitted, repmat('0', 1, maxLength - length(transmitted))];
    received = [received, repmat('0', 1, maxLength - length(received))];
    errors = sum(transmitted ~= received);
    ber = errors / maxLength;
end
```

