    {'name': 'Mercury', 'radius': 0.387, 'period': 88, 'color': '#A9A9A9', 'mass': 3.3011e23},
    {'name': 'Venus', 'radius': 0.723, 'period': 224.7, 'color': '#FFD700', 'mass': 4.8675e24},
