    {'name': 'Mars', 'radius': 1.524, 'period': 687, 'color': '#FF4500', 'mass': 6.4171e23},
    {'name': 'Jupiter', 'radius': 5.203, 'period': 4331, 'color': '#FFA500', 'mass': 1.8982e27}
]

def calculate_position(time_days, planet):
    angular_velocity = 2 * math.pi / planet['period']
    theta = angular_velocity * time_days
    return (planet['radius'] * math.cos(theta), planet['radius'] * math.sin(theta))

def generate_data():
    days = datetime.now().timestamp() / (24*3600)
    return {
        'planets': [{
            'name': p['name'],
            'color': p['color'],
            'position': [calculate_position(days, p)[0]*AU, calculate_position(days, p)[1]*AU]
        } for p in PLANETARY_DATA]
    }

if __name__ == "__main__":
    with open('solar_system_data.json', 'w') as f:
        json.dump(generate_data(), f)
