// Simulation constants
const CENTER = { x: canvas.width/2, y: canvas.height/2 };
const SUN_RADIUS = 30;

function drawSun() {
    const gradient = ctx.createRadialGradient(CENTER.x, CENTER.y, 0, CENTER.x, CENTER.y, SUN_RADIUS);
    gradient.addColorStop(0, '#FFFF00');
    gradient.addColorStop(1, '#FFA500');
    ctx.beginPath();
    ctx.arc(CENTER.x, CENTER.y, SUN_RADIUS, 0, Math.PI*2);
    ctx.fillStyle = gradient;
    ctx.fill();
}

function drawPlanet(planet, position) {
    ctx.beginPath();
    ctx.arc(position.x, position.y, 5, 0, Math.PI*2);
    ctx.fillStyle = planet.color;
    ctx.fill();

    // Optional: Draw orbit lines
    ctx.beginPath();
    ctx.strokeStyle = 'rgba(255,255,255,0.1)';
    ctx.arc(CENTER.x, CENTER.y, planet.orbitalRadius/scale, 0, Math.PI*2);
    ctx.stroke();
}

function update() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawSun();

