# Constants
AU = 149.6e6  # 1 Astronomical Unit in kilometers
G = 6.67430e-11  # Gravitational constant (m^3 kg^-1 s^-2)
J2000_EPOCH = datetime(2000, 1, 1, 12, 0, 0)  # J2000 epoch

# NASA Horizons API endpoint
HORIZONS_API = "https://ssd.jpl.nasa.gov/horizons_batch.cgi"

def get_planetary_data_from_horizons(body_id, start_date):
    """
    Fetch planetary data from NASA Horizons API

    Args:
        body_id: JPL Horizons body ID
        start_date: Start date for ephemeris (datetime object)

    Returns:
        Dictionary containing orbital elements
    """
    date_str = start_date.strftime("%Y-%b-%d %H:%M")

    # Horizons API request parameters
    params = {
        "batch": 1,
        "COMMAND": body_id,
        "CENTER": "@sun",
        "START_TIME": date_str,
        "STOP_TIME": date_str,
        "STEP_SIZE": "1 day",
        "OUT_UNITS": "AU-D",
        "REF_PLANE": "ecliptic",
        "REF_SYSTEM": "J2000",
        "ELEM_LABELS": "yes",
        "CSV_FORMAT": "yes"
    }

    try:
        response = requests.get(HORIZONS_API, params=params)
        data = response.text

        # Parse Horizons response (simplified for this example)
        # In a real implementation, you would parse the full ephemeris data
        return {
            "semi_major_axis": 1.0,  # AU (from Horizons response)
            "eccentricity": 0.1,     # (from Horizons response)
            "inclination": 0.0,      # degrees
            "longitude_of_node": 0.0,
            "argument_of_perihelion": 0.0,
            "mean_anomaly": 0.0,     # at epoch
            "epoch": date_str
        }
    except Exception as e:
        print(f"Error fetching data from Horizons: {e}")
        return None

def calculate_elliptical_position(orbital_elements, time_days):
    """
    Calculate position using Kepler's equation for elliptical orbits

    Args:
        orbital_elements: Dictionary with orbital parameters
        time_days: Time in days since epoch

    Returns:
        (x, y) coordinates in AU
    """
    # Convert orbital elements to radians
    inclination = math.radians(orbital_elements["inclination"])
    lon_node = math.radians(orbital_elements["longitude_of_node"])
    arg_peri = math.radians(orbital_elements["argument_of_perihelion"])

    # Mean motion (radians per day)
    n = 2 * math.pi / 365.25  # Simplified for this example

    # Mean anomaly at time t
    M = math.radians(orbital_elements["mean_anomaly"]) + n * time_days

    # Solve Kepler's equation for eccentric anomaly E
    E = solve_keplers_equation(M, orbital_elements["eccentricity"])

    # Calculate position in orbital plane
    x_orb = orbital_elements["semi_major_axis"] * (math.cos(E) - orbital_elements["eccentricity"])
    y_orb = orbital_elements["semi_major_axis"] * math.sqrt(1 - orbital_elements["eccentricity"]**2) * math.sin(E)

    # Rotate to ecliptic coordinates
    x = (math.cos(arg_peri) * math.cos(lon_node) - math.sin(arg_peri) * math.sin(lon_node) * math.cos(inclination)) * x_orb + \
        (-math.sin(arg_peri) * math.cos(lon_node) - math.cos(arg_peri) * math.sin(lon_node) * math.cos(inclination)) * y_orb

    y = (math.cos(arg_peri) * math.sin(lon_node) + math.sin(arg_peri) * math.cos(lon_node) * math.cos(inclination)) * x_orb + \
        (-math.sin(arg_peri) * math.sin(lon_node) + math.cos(arg_peri) * math.cos(lon_node) * math.cos(inclination)) * y_orb

    z = math.sin(arg_peri) * math.sin(inclination) * x_orb + math.cos(arg_peri) * math.sin(inclination) * y_orb

    return (x, y)  # Return x, y in AU

def solve_keplers_equation(M, e, tolerance=1e-8):
    """
    Solve Kepler's equation M = E - e*sin(E)

    Args:
        M: Mean anomaly (radians)
        e: Eccentricity
        tolerance: Solution tolerance

    Returns:
        Eccentric anomaly E (radians)
    """
    # Use Newton-Raphson method to solve for E
    M = M % (2 * math.pi)
    if e < 0.8:
        E = M
    else:
        E = math.pi

    while True:
        delta = (E - e * math.sin(E) - M) / (1 - e * math.cos(E))
        E -= delta
        if abs(delta) < tolerance:
            break

    return E

def calculate_jd(date):
    """Calculate Julian Date"""
    time_delta = date - J2000_EPOCH
    return 2451545.0 + time_delta.total_seconds() / (24 * 3600)

